// src/pages/Chat.js
import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/Chat.css";

const Chat = () => {
  const user = JSON.parse(localStorage.getItem("user"));
  console.log("✅ Logged in user:", user);

  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [search, setSearch] = useState("");
  const [newMessage, setNewMessage] = useState("");

  // ✅ Load conversations on mount
  useEffect(() => {
    if (!user?._id) return;
    axios
      .get(`http://localhost:5000/api/conversations/${user._id}`)
      .then((res) => setConversations(res.data))
      .catch((err) => console.error("Error loading conversations", err));
  }, [user?._id]);

  // ✅ Load messages when conversation selected
  useEffect(() => {
    if (!selectedConversation?._id) return;
    axios
      .get(`http://localhost:5000/api/messages/${selectedConversation._id}`)
      .then((res) => setMessages(res.data))
      .catch((err) => console.error("Error loading messages", err));
  }, [selectedConversation]);

  const handleSend = () => {
    if (!newMessage || !selectedConversation) return;
    const messageData = {
      conversationId: selectedConversation._id,
      senderId: user._id,
      senderUsername: user.username,
      receiverId: selectedConversation.members.find((m) => m !== user._id),
      receiverUsername: selectedConversation.participantUsernames.find((u) => u !== user.username),
      text: newMessage,
    };

    axios
      .post("http://localhost:5000/api/messages", messageData)
      .then((res) => {
        setMessages((prev) => [...prev, res.data]);
        setNewMessage("");
      })
      .catch((err) => console.error("Error sending message", err));
  };

  return (
    <div className="chat-container">
      <div className="chat-sidebar">
        <input
          type="text"
          placeholder="Search by username..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <ul>
          {conversations
            .filter((conv) =>
              conv.participantUsernames.some(
                (name) =>
                  name !== user.username &&
                  name.toLowerCase().includes(search.toLowerCase())
              )
            )
            .map((conv) => (
              <li key={conv._id} onClick={() => setSelectedConversation(conv)}>
                {conv.participantUsernames.find((n) => n !== user.username)}
                <br />
                <small>{conv.lastMessage}</small>
              </li>
            ))}
        </ul>
      </div>

      <div className="chat-main">
        {selectedConversation ? (
          <>
            <div className="chat-messages">
              {messages.map((msg) => (
                <div
                  key={msg._id}
                  className={`chat-bubble ${
                    msg.senderId === user._id ? "sent" : "received"
                  }`}
                >
                  {msg.text}
                  <span className="timestamp">
                    {new Date(msg.timestamp).toLocaleString()}
                  </span>
                </div>
              ))}
            </div>

            <div className="chat-input">
              <input
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                placeholder="Type a message..."
              />
              <button onClick={handleSend}>Send</button>
            </div>
          </>
        ) : (
          <p className="chat-empty">Select a conversation to start chatting.</p>
        )}
      </div>
    </div>
  );
};

export default Chat;
